using Essco.Application.Purchasing;using Essco.Application.Security;using Essco.Domain.Purchasing;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;
namespace Essco.Web.Pages.Purchasing;
[Authorize(Policy=Permissions.Billing)]public sealed class DetailModel(PurchaseOrderService service):PageModel{public PurchaseOrder?Order{get;private set;}[BindProperty]public LineInput Input{get;set;}=new();[TempData]public string?StatusMessage{get;set;}public async Task<IActionResult>OnGetAsync(int number,long?edit,CancellationToken t){Order=await service.GetAsync(number,t);if(Order is null)return NotFound();var l=Order.Lines.FirstOrDefault(x=>x.Id==edit);if(l is not null)Input=LineInput.From(l);return Page();}public async Task<IActionResult>OnPostSaveAsync(int number,CancellationToken t){var order=await service.GetAsync(number,t);if(order is null)return NotFound();var original=order.Lines.FirstOrDefault(x=>x.Id==Input.Id);if(original is null)return NotFound();var line=original with{Units=Input.Units,Cases=Input.Cases,Total=Input.Total,Reason=Input.Reason};var r=await service.UpdateLineAsync(number,line,t);if(r.Succeeded){StatusMessage="Línea actualizada.";return RedirectToPage(new{number});}foreach(var e in r.Errors)ModelState.AddModelError("",e);Order=order;return Page();}public sealed class LineInput{public long Id{get;set;}public decimal Units{get;set;}public decimal Cases{get;set;}public decimal Total{get;set;}public string Reason{get;set;}="";public static LineInput From(PurchaseOrderLine x)=>new(){Id=x.Id,Units=x.Units,Cases=x.Cases,Total=x.Total,Reason=x.Reason};}}
